import java.util.Scanner;

public class Main {
    public static long computeGCD(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static class Fraction {
        long num, den;

        Fraction() {
            this.num = 0;
            this.den = 1;
        }

        Fraction(long n, long d) {
            this.num = n;
            this.den = d;
        }

        void simplify() {
            long g = computeGCD(num, den);
            num /= g;
            den /= g;
        }

        boolean lessThan(Fraction other) {
            return this.num * other.den < other.num * this.den;
        }

        void printFraction() {
            System.out.print(num + "/" + den);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long count = sc.nextLong();

        Fraction limit = new Fraction(50, 1);
        Fraction base = new Fraction(a, b);
        long minR = 0, minI = 1;

        for (long i = 1; i <= count; ++i) {
            long r = (base.num * i) / base.den;
            long z = (base.num * i) % base.den;
            if (z > base.den / 2) {
                r++;
                z = base.den - z;
            }
            Fraction current = new Fraction(z, i * base.den);
            if (current.lessThan(limit)) {
                limit = current;
                minR = r;
                minI = i;
            }
        }
        System.out.println(minR);
        sc.close();
    }
}
